files.concepts.memql:
/// A loop scenario row.
@namespace("looppair")
concept left {
  key string
  status string
  n int
}
/// A loop scenario row.
@namespace("looppair")
concept right {
  key string
  status string
  n int
}

files.mutations.memql:
/// Write a scenario row.
mutation left loopPairCreateLeft {
  args {
    id string!
    status string
    n int
  }
  insert {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}
/// Write a scenario row.
mutation right loopPairCreateRight {
  args {
    id string!
    status string
    n int
  }
  insert {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}
/// Write a scenario row.
mutation left loopPairWriteLeft {
  args {
    id string!
    status string
    n int
  }
  update {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}
/// Write a scenario row.
mutation right loopPairWriteRight {
  args {
    id string!
    status string
    n int
  }
  update {
    id: args.id
    key: args.id
    status: args.status
    n: args.n
  }
}

scenarios.automations:
/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:looppair:left")
@filter(row => row.status != "done")
automation loopPairForward {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopPairWriteRight(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}
/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:looppair:right")
@filter(row => row.status != "done")
automation loopPairMirror {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopPairWriteLeft(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}

/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:looppair:left")
@filter(row => row.status != "done")
automation loopPairForward {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopPairWriteRight(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}
/// Exercise a causal loop.
@trigger(event="node.created", concept="v1:looppair:right")
@filter(row => row.status != "done")
@loop(maxDepth=4, until=row => row.status == "done")
automation loopPairMirror {
  args {
    id any
    key any
    status any
    n any
  }
  mutation loopPairWriteLeft(id: args.key, n: args.n + 1, status: args.n >= 1 ? "done" : "open")
}
